      "obligations": "Mise en œuvre d'un référentiel de mesures de cybersécurité basé sur les articles 20 et 21 de NIS 2;Respect d'un niveau d'exigences différencié selon le statut EE ou EI;Transposition des mesures dans les textes législatifs et réglementaires français;Communication obligatoire d'informations à l'autorité nationale compétente;Application de mesures de sécurité sur l'ensemble du système d'information (SI);Intégration du principe de proportionnalité dans la gestion des risques",
      "impact": "9",
      "entities": "Entités essentielles (EE);Entités importantes (EI);Opérateurs de services essentiels;Fournisseurs de services numériques;Autorités nationales compétentes",
      "publishedOn": "2025-03-19",
